export function getHadithGrades(bookSlug: string, idInBook: number): HadithScholarGrade[] {
  return HADITH_GRADES[`${bookSlug}:${idInBook}`] ?? [];
}

export function getStrictestHadithGrade(bookSlug: string, idInBook: number): HadithGrade | null {
  const grades = getHadithGrades(bookSlug, idInBook);

  if (grades.length === 0 || grades[0] === undefined) {
    return null;
  }

  const severity: Record<HadithGrade, number> = {
    Sahih: 1,
    Hasan: 2,
    "Da'if": 3,
  };

  return grades.reduce<HadithGrade>((strongest, current) => {
    return severity[current.grade] > severity[strongest] ? current.grade : strongest;
  }, grades[0].grade);
}
